fun formatReading(reading: Double?): String {
    return reading?.let { "Reading: $it" } ?: "No reading"
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithValue() {
        Assert.assertEquals("Reading: 42.5", formatReading(42.5))
    }

    @Test
    fun testWithNull() {
        Assert.assertEquals("No reading", formatReading(null))
    }

    @Test
    fun testWithZero() {
        Assert.assertEquals("Reading: 0.0", formatReading(0.0))
    }

    @Test
    fun testWithNegative() {
        Assert.assertEquals("Reading: -5.3", formatReading(-5.3))
    }
}
